            var lower = detail.ToLowerInvariant();
            if (detail.Length > 140
                || ContainsAny(lower,
                    "scene to imagine only as background context",
                    "room overview",
                    "whole room",
                    "full room",
                    "empty room",
                    "interior design",
                    "architectural rendering",
                    "wide shot",
                    "long shot",
                    "establishing shot",
                    "no text",
                    "no letters",
                    "no captions",
                    "watermark"))
            {
                return string.Empty;
            }

            return detail;
        }

