                    && hasPreview == other.hasPreview
                    && isValid == other.isValid
                    && gridX == other.gridX
                    && gridZ == other.gridZ
                    && rotation == other.rotation
                    && wallDirection == other.wallDirection
                    && reason == other.reason;
